using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Net.WebSockets;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Management;
namespace XzyBattleStats {
sealed class BrowserSession:IDisposable {
 readonly ClientWebSocket socket=new ClientWebSocket();int id;readonly CancellationToken token;
 public BrowserSession(CancellationToken cancel){token=cancel;}
 public async Task Connect(string address,int port){var u=new Uri(address);if(u.Scheme!="ws"||u.Host!="127.0.0.1"||u.Port!=port||!u.AbsolutePath.StartsWith("/devtools/page/"))throw new Exception("官网账号网页调试地址无效");await socket.ConnectAsync(u,token);}
 public async Task<object> Command(string method,object parameters){int seq=++id;byte[] bytes=Encoding.UTF8.GetBytes(J.Json.Serialize(new{id=seq,method=method,@params=parameters}));await socket.SendAsync(new ArraySegment<byte>(bytes),WebSocketMessageType.Text,true,token);while(true){using(var outp=new MemoryStream()){WebSocketReceiveResult r;byte[] buf=new byte[32768];do{r=await socket.ReceiveAsync(new ArraySegment<byte>(buf),token);if(r.MessageType==WebSocketMessageType.Close)throw new Exception("官网账号网页已关闭");if(outp.Length+r.Count>128L*1024*1024)throw new Exception("官网结果过大");outp.Write(buf,0,r.Count);}while(!r.EndOfMessage);object response=J.Json.DeserializeObject(Encoding.UTF8.GetString(outp.ToArray()));if(J.Get(response,"id")==null||J.Num(J.Get(response,"id"))!=seq)continue;if(J.Get(response,"error")!=null)throw new Exception(J.Str(J.Get(response,"error"),"message"));return J.Get(response,"result");}}}
 public async Task<object> Eval(string expression){var r=await Command("Runtime.evaluate",new{expression=expression,returnByValue=true,awaitPromise=false});if(J.Get(r,"exceptionDetails")!=null)throw new Exception("官网脚本执行失败，请更新官网获取脚本");return J.Get(J.Get(r,"result"),"value");}
 public void Dispose(){socket.Dispose();}
}
static class RefreshBrowser {
 public static object Local(int port,string path,string method="GET"){if(port<1024||port>65535)throw new Exception("账号网页端口无效");var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+path);r.Proxy=null;r.Method=method;r.Timeout=r.ReadWriteTimeout=3000;using(var response=r.GetResponse())using(var input=response.GetResponseStream())using(var reader=new StreamReader(input,Encoding.UTF8)){return J.Json.DeserializeObject(reader.ReadToEnd());}}
 public static int Ensure(string root,int slot){string dir=OfficialProfiles.Slot(root,slot),profile=Path.Combine(dir,"profile"),record=Path.Combine(dir,"automation.json");try{var old=J.Json.DeserializeObject(File.ReadAllText(record));int port=(int)J.Num(J.Get(old,"Port")),pid=(int)J.Num(J.Get(old,"Pid"));using(var process=Process.GetProcessById(pid))using(var wmi=new ManagementObject("Win32_Process.Handle='"+pid+"'")){wmi.Get();string args=Convert.ToString(wmi["CommandLine"]);if(!process.HasExited&&args.IndexOf("--user-data-dir=\""+profile+"\"",StringComparison.OrdinalIgnoreCase)>=0&&args.Contains("--remote-debugging-port="+port)){Local(port,"/json/version");return port;}}}catch{}
  OfficialProfiles.Prepare(root,slot,File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"官网导出助手.js")));int chosen;var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();chosen=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();var p=Process.Start(new ProcessStartInfo(OfficialProfiles.Browser(),"--user-data-dir=\""+profile+"\" --remote-debugging-address=127.0.0.1 --remote-debugging-port="+chosen+" --no-first-run --no-default-browser-check --new-window about:blank"){UseShellExecute=false});File.WriteAllText(record,J.Json.Serialize(new{Port=chosen,Pid=p.Id}),new UTF8Encoding(false));return chosen;
 }
 public static void Remember(string root,int slot,string uid,string game,string name){File.WriteAllText(Path.Combine(OfficialProfiles.Slot(root,slot),"identity.json"),J.Json.Serialize(new{Uid=uid,GameCode=game,Name=name}),new UTF8Encoding(false));}
 public static int Find(string root,Snapshot target){for(int i=1;i<=8;i++)try{var p=J.Json.DeserializeObject(File.ReadAllText(Path.Combine(OfficialProfiles.Slot(root,i),"identity.json")));if(J.Str(p,"Uid")==target.Uid&&J.Str(p,"GameCode").Equals(target.GameCode,StringComparison.OrdinalIgnoreCase))return i;}catch{}return 0;}
 public static bool Complete(Battle b){string[] fields=b.Mode>20?new[]{"ExportDamage","Debarrass","BeatCnt","BeatedCnt","BeatFreidnCnt","BeatAwakeCnt"}:new[]{"ExportDamage","AliveCnt","BeatAwakeCnt"};int size=b.Mode>20?2:1;return b.DetailStatus=="ok"&&(b.Mode<20||(b.TeamDetailStatus=="ok"&&(!string.IsNullOrEmpty(b.AllyUid)||!string.IsNullOrEmpty(b.AllyName))))&&new[]{b.MyTeamPlayers,b.EnemyTeamPlayers}.All(ps=>ps.Count==size&&ps.All(p=>fields.All(f=>typeof(Player).GetField(f).GetValue(p)!=null)))&&((b.Mode!=12&&b.Mode!=22)||(b.ScoreBefore.HasValue&&b.ScoreAfter.HasValue&&new[]{b.MyTeamPlayers,b.EnemyTeamPlayers}.All(ps=>ps.All(p=>p.ScoreBefore.HasValue&&p.ScoreAfter.HasValue))));}
 public static string Script(Snapshot s,string mobile){string target=J.Json.Serialize(new{Uid=s.Uid,GameCode=s.GameCode,SeasonCode=s.SeasonCode,Name=s.Name,SeasonName=s.SeasonName});string index=J.Json.Serialize(new{Enabled=true,Records=s.Battles.Select(b=>new{b.Id,b.Mode,b.Start,b.Result,b.Damage,b.Kills,b.Deaths,b.Mvp,Complete=Complete(b)}).ToArray()});return "window.__xzyAutoRefresh="+target+";window.__xzyDesktopData=null;window.__xzyDesktopResult=null;window.XzyExport={knownRecords:function(game,uid,season){if(game.toUpperCase()!==window.__xzyAutoRefresh.GameCode.toUpperCase()||uid!==window.__xzyAutoRefresh.Uid||Number(season)!==window.__xzyAutoRefresh.SeasonCode)throw Error('增量索引账号不匹配');return "+J.Json.Serialize(index)+";},receiveExport:function(text){window.__xzyDesktopData=text;return '';},autoFinished:function(ok,message,auth){window.__xzyDesktopResult={Ok:ok,Message:message,Auth:auth,Data:window.__xzyDesktopData};}};\n"+mobile;}
 static string Save(string root,int slot,Snapshot target,string raw){string dir=Path.Combine(OfficialProfiles.Slot(root,slot),"downloads");Directory.CreateDirectory(dir);string stem=Guid.NewGuid().ToString("N"),tmp=Path.Combine(dir,stem+".pending"),path=Path.Combine(dir,stem+".json");File.WriteAllText(tmp,raw,new UTF8Encoding(false));try{var snap=Stats.Decode(tmp);if(snap.Uid!=target.Uid||!snap.GameCode.Equals(target.GameCode,StringComparison.OrdinalIgnoreCase)||snap.SeasonCode!=target.SeasonCode)throw new Exception("官网结果与刷新目标不一致，未导入其他账号");File.Move(tmp,path);return path;}catch{if(File.Exists(tmp))File.Delete(tmp);throw;}}
 public static async Task Stop(string address,int port,string root,int slot,Snapshot target){try{using(var browser=new BrowserSession(CancellationToken.None)){await browser.Connect(address,port);await browser.Eval("(function(){var e=document.getElementById('xzy-season-export-progress');if(e&&e.dataset.finished!=='true'){var b=e.querySelector('button');if(b)b.click();}})()");for(int i=0;i<30;i++){var result=await browser.Eval("window.__xzyDesktopResult||null");if(result!=null){string raw=J.Str(result,"Data");if(raw!="")Save(root,slot,target,raw);break;}await Task.Delay(1000);}}}catch{}}
 public static async Task<string> Run(string root,int slot,Snapshot s,string script,CancellationToken token,Action<string> progress){int port=Ensure(root,slot);bool ready=false;for(int i=0;i<40;i++){token.ThrowIfCancellationRequested();try{Local(port,"/json/version");ready=true;break;}catch{}await Task.Delay(250,token);}if(!ready)throw new Exception("无法连接独立账号网页。若此网页仍在旧版窗口中运行，请关闭该账号网页窗口后重试刷新。");var tab=Local(port,"/json/new?"+Uri.EscapeDataString(OfficialProfiles.Page),"PUT");using(var browser=new BrowserSession(token)){await browser.Connect(J.Str(tab,"webSocketDebuggerUrl"),port);using(var registration=token.Register(()=>{var stop=Stop(J.Str(tab,"webSocketDebuggerUrl"),port,root,slot,s);})){bool running=false;string saved="";var expiry=DateTime.UtcNow.AddMinutes(30);while(DateTime.UtcNow<expiry){token.ThrowIfCancellationRequested();if(!running){object info=null;try{info=await browser.Eval("(function(){if(location.origin!=='https://xzy.shengtiangames.com'||location.pathname!=='/gamerecords_2/dist/index.html')return {};var u={};try{u=JSON.parse(localStorage.getItem('userInfo')||'{}');}catch(e){}var langs={'zh-CN':'XZY','zh-Hans':'XZY','zh-HK':'XZYGAT','zh-Hant':'XZYGAT','zh-TW':'XZYGAT',en:'XZYSteam','en-US':'XZYSteam',ja:'XZYJP'},token=localStorage.getItem('token');return {Uid:String(localStorage.getItem('selected_role_id')||u.role_id||''),GameCode:langs[localStorage.getItem('xzy_select_lang')||localStorage.getItem('i18nextLng')||'zh-CN']||'XZY',LoggedIn:!!token,Ready:!!token&&token!==window.__xzyAutoFailedToken};})()");}catch{}if(info==null){await Task.Delay(1500,token);continue;}if(J.Str(info,"Uid")==s.Uid&&J.Str(info,"GameCode").Equals(s.GameCode,StringComparison.OrdinalIgnoreCase)&&J.Bool(J.Get(info,"LoggedIn"))&&J.Bool(J.Get(info,"Ready"))){progress("账号网页 "+slot+"：正在增量刷新 "+s.Name+" / "+s.SeasonName);await browser.Eval(script);running=true;}else progress("账号网页 "+slot+"：请登录 / 绑定 "+s.Name+"（"+s.GameCode+"），验证完成后自动继续；可点击停止刷新。");}else{var result=await browser.Eval("window.__xzyDesktopResult||null");if(result!=null){string raw=J.Str(result,"Data");if(raw!="")saved=Save(root,slot,s,raw);if(J.Bool(J.Get(result,"Auth"))){running=false;progress("账号网页 "+slot+"：登录已过期，请在官网重新验证后自动继续。");}else{if(!J.Bool(J.Get(result,"Ok")))throw new Exception(J.Str(result,"Message")+(saved!=""?"；部分结果已保存，程序会自动合并。":""));Remember(root,slot,s.Uid,s.GameCode,s.Name);return J.Str(result,"Message");}}else{string label=J.Text(await browser.Eval("(function(){var e=document.getElementById('xzy-season-export-progress');return e&&e.children[1]?e.children[1].textContent:'正在读取官网…';})()"));progress("账号网页 "+slot+"："+label);}}await Task.Delay(1000,token);}throw new Exception("刷新等待超过 30 分钟，请重新刷新；已保存结果会自动合并。");}}}
}
sealed partial class NativeForm {
 CancellationTokenSource refreshCancellation;
 int ChooseRefreshSlot(Snapshot s){int known=RefreshBrowser.Find(OfficialProfiles.Root,s);if(known>0)return known;using(var d=new Form{Text="首次指定账号网页 · "+s.Name,Width=540,Height=220,StartPosition=FormStartPosition.CenterParent,BackColor=BackColor,ForeColor=ForeColor,Font=Font}){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Top};for(int i=1;i<=8;i++)c.Items.Add("账号网页 "+i);c.SelectedIndex=0;d.Controls.Add(c);d.Controls.Add(new Label{Dock=DockStyle.Top,Height=80,Padding=new Padding(8),Text="选择 "+s.Name+"（"+s.GameCode+"）对应的独立登录网页。首次完成官网验证后会记住对应关系；以后刷新会自动使用。"});var b=new Button{Text="开始刷新",Dock=DockStyle.Bottom,Height=36};b.Click+=delegate{d.DialogResult=DialogResult.OK;};d.Controls.Add(b);return d.ShowDialog(this)==DialogResult.OK?c.SelectedIndex+1:0;}}
 async void StartBattleRefresh(){if(refreshCancellation!=null)return;ShowOperationStatus(battleRefreshStatus);try{RequireData();var targets=(data.IsAggregate?data.ViewSources:new List<Snapshot>{data}).Where(s=>!s.Demo).GroupBy(Merge.Key).Select(g=>g.First()).ToList();if(targets.Count==0)throw new Exception("演示账号不能查询官网");var slots=new List<int>();foreach(var target in targets){int slot=ChooseRefreshSlot(target);if(slot==0)return;slots.Add(slot);}refreshCancellation=new CancellationTokenSource();battleRefreshButton.Enabled=false;battleStopButton.Enabled=true;string asset=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"自动刷新战绩.js"));for(int i=0;i<targets.Count;i++){var target=ReadSources().FirstOrDefault(s=>Merge.Key(s)==Merge.Key(targets[i]))??targets[i];int slot=slots[i];string script=RefreshBrowser.Script(target,asset);string result=await Task.Run(()=>RefreshBrowser.Run(OfficialProfiles.Root,slot,target,script,refreshCancellation.Token,message=>{if(!IsDisposed)BeginInvoke((Action)(()=>{battleRefreshStatus.Text=status.Text=message;}));}));PollOfficial();if(officialImportFailed)throw new Exception("已取得结果，但自动合并失败；文件保留在下载队列，请查看操作状态后重试。");battleRefreshStatus.Text=status.Text=result;}battleRefreshStatus.Text=status.Text="刷新完成：已处理 "+targets.Count+" 个账号赛季，结果已自动合并。";}catch(OperationCanceledException){battleRefreshStatus.Text=status.Text="已停止刷新；已保存结果会自动合并。";PollOfficial();}catch(Exception e){battleRefreshStatus.Text=status.Text="刷新未完成："+e.Message;PollOfficial();}finally{if(refreshCancellation!=null){refreshCancellation.Dispose();refreshCancellation=null;}battleRefreshButton.Enabled=true;battleStopButton.Enabled=false;}}
}
}
